/* Intermediate8: cache-aside data correctness plus explicitly bounded managed-cache metadata. */
(function(){
  const N=AG.aws.n,clone=x=>JSON.parse(JSON.stringify(x)),wrap=x=>'<div class="tbl-wrap">'+x+'</div><p class="muted">Phone par baaki columns dekhne ke liye table ko side mein swipe karo.</p>';
  function Q(q,correct,wrong,answer,explain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};}
  const ROLE='arn:aws:iam::123456789012:role/cart-dax-read';
  function seed(){return {region:'ap-south-1',vpcs:[{id:'vpc-shop',cidr:'10.216.0.0/16',name:'shop',default:false}],subnets:['a','b','c'].map((az,i)=>({id:'subnet-cache-'+az,vpcId:'vpc-shop',az:'ap-south-1'+az,cidr:'10.216.'+(i+1)+'.0/24',public:false,name:'cache-'+az})),securityGroups:[{id:'sg-app',vpcId:'vpc-shop',name:'catalog-app',ingress:[],egress:[{protocol:'tcp',fromPort:6379,toPort:6379,destinationGroup:'sg-cache'},{protocol:'tcp',fromPort:9111,toPort:9111,destinationGroup:'sg-cache'}]},{id:'sg-cache',vpcId:'vpc-shop',name:'catalog-cache',ingress:[{protocol:'tcp',fromPort:6379,toPort:6379,cidr:'0.0.0.0/0'}],egress:[]}],cacheSubnetGroups:[{name:'shop-cache-private',subnetIds:['subnet-cache-a','subnet-cache-b','subnet-cache-c']}],daxSubnetGroups:[{name:'shop-dax-private',subnetIds:['subnet-cache-a','subnet-cache-b','subnet-cache-c']}],cacheUserGroups:[{id:'catalog-app',engine:'valkey',status:'active',scope:'catalog:shop:*',permissions:['get','set','del','expire']}],roles:[{name:'cart-dax-read',arn:ROLE,daxTrust:'dax.amazonaws.com',daxReadTables:['carts']}],tables:[{name:'carts',tableId:'22222222-2222-4222-8222-222222222222',partitionKey:'cartId',billing:'PAY_PER_REQUEST',items:[{cartId:'cart-101',total:499,version:1}]}],rds:[{id:'shop-orders',name:'shop-orders',engine:'postgres',class:'db.m7g.large',storage:100,port:5432,state:'available',multiAZ:true,endpoint:'shop-orders.local-fixture.rds.amazonaws.com'}],cacheGroups:[],daxClusters:[]};}
  const cache=s=>(s.account.cacheGroups||[]).find(g=>g.id==='catalog-cache');
  function preserve(s){const a=seed();return ['vpcs','subnets','cacheSubnetGroups','daxSubnetGroups','cacheUserGroups','roles','rds'].every(k=>JSON.stringify(s.account[k])===JSON.stringify(a[k]))&&JSON.stringify((s.account.tables||[]).map(t=>({name:t.name,tableId:t.tableId,partitionKey:t.partitionKey,billing:t.billing,items:t.items})))===JSON.stringify(a.tables.map(t=>({name:t.name,tableId:t.tableId,partitionKey:t.partitionKey,billing:t.billing,items:t.items})))&&JSON.stringify(s.account.securityGroups.find(g=>g.id==='sg-app'))===JSON.stringify(a.securityGroups[0]);}
  function privateRule(s,port){const sg=(s.account.securityGroups||[]).find(g=>g.id==='sg-cache');return !!sg&&sg.vpcId==='vpc-shop'&&sg.ingress.length===1&&sg.ingress[0].protocol==='tcp'&&sg.ingress[0].fromPort===port&&sg.ingress[0].toPort===port&&sg.ingress[0].sourceGroup==='sg-app'&&!sg.ingress[0].cidr;}
  function cacheReady(s){const g=cache(s);return !!g&&s.account.cacheGroups.length===1&&(s.account.daxClusters||[]).length===0&&g.status==='available'&&!g.pending&&g.engine==='valkey'&&g.engineVersion==='8.0'&&g.port===6379&&g.nodeType==='cache.t4g.small'&&g.subnetGroup==='shop-cache-private'&&g.vpcId==='vpc-shop'&&g.nodes.length===2&&g.nodes.every(n=>n.status==='available')&&g.nodes.filter(n=>n.role==='primary').length===1&&g.nodes.filter(n=>n.role==='replica').length===1&&new Set(g.nodes.map(n=>n.az)).size===2&&g.nodes.every(n=>['ap-south-1a','ap-south-1b'].includes(n.az));}
  const SOLUTION=[
    'aws ec2 revoke-security-group-ingress --group-id sg-cache --protocol tcp --port 6379 --cidr 0.0.0.0/0',
    'aws ec2 authorize-security-group-ingress --group-id sg-cache --protocol tcp --port 6379 --source-group sg-app',
    "aws elasticache create-replication-group --replication-group-id catalog-cache --replication-group-description 'ShopKaro catalogue cache' --engine valkey --engine-version 8.0 --cache-node-type cache.t4g.small --num-cache-clusters 2 --preferred-cache-cluster-azs ap-south-1a ap-south-1b --cache-subnet-group-name shop-cache-private --security-group-ids sg-cache --transit-encryption-enabled --at-rest-encryption-enabled --user-group-ids catalog-app",
    'aws elasticache wait replication-group-available --replication-group-id catalog-cache',
    'aws elasticache modify-replication-group --replication-group-id catalog-cache --automatic-failover-enabled --multi-az-enabled --apply-immediately',
    'aws elasticache wait replication-group-available --replication-group-id catalog-cache',
    'aws elasticache describe-replication-groups --replication-group-id catalog-cache'
  ];
  const TASKS=[{text:'Purana DB/cart data, subnet groups, app SG, RBAC aur role ka metadata bacha raha',check:preserve},{text:'Cache ke port 6379 tak sirf app SG pahunch sakta hai; public rule hata',check:s=>privateRule(s,6379)},{text:'Ek ready traditional Valkey 8.0 cache: do chhote nodes, AZ-a/b mein primary + replica',check:cacheReady},{text:'Automatic failover + Multi-AZ on; transit/at-rest encryption aur scoped RBAC laga',check:s=>{const g=cache(s);return !!g&&g.automaticFailover&&g.multiAZ&&g.transitEncryption&&g.atRestEncryption&&g.userGroupIds.length===1&&g.userGroupIds[0]==='catalog-app'&&g.securityGroupIds.length===1&&g.securityGroupIds[0]==='sg-cache';}},{text:'Aakhri describe ready config aur dono asli node/AZ records lautata hai',check:s=>{const g=cache(s),r=s.cacheRead?.service==='elasticache'&&s.cacheRead.groups.find(r=>r.id==='catalog-cache');return !!g&&!!r&&r.revision===g.revision&&r.record.Status==='available'&&r.record.MemberClusters.length===2&&r.record.NodeGroups[0].NodeGroupMembers.length===2;}}];
  function plan(k){const products=1000,capacity=Math.min(1,k.memory*1024/(products*2*1.5)),perRead=k.reads/products,perWrite=k.writes/products,lifetime=(1-Math.exp(-perWrite*k.ttl))/perWrite,hit=k.key?capacity*(perRead*lifetime)/(1+perRead*lifetime):0,miss=k.reads*(1-hit),db=miss*40,ecpu=(k.reads*2+miss*2+k.writes)*30*86400,serverless=.1*.084*720+ecpu*.0000000023,nodes=2*.0256*720;return {hit,miss,db,capacity,serverless,nodes,burst:k.refill?1:200,ok:k.reads>=1000&&k.writes>=3&&k.ttl<=60&&hit>=.95&&db<=1000&&k.refill===1};}
  AG.registerLevels('intermediate',[{
    id:'caching',icon:'⚡',title:'Caching: sahi keys, taaza data aur safe refill',badge:'Cache Chatur',
    objectives:['<b>Kyun:</b> baar-baar ki catalogue queries kam karo; checkout ka sahi hona bachao','<b>Tareeka:</b> cache-aside, write-through, write-behind aur invalidation','<b>Key:</b> jawaab ka scope, TTL, eviction, negative cache aur stampede (ek saath bheed)','<b>Service:</b> Valkey/Redis OSS/Memcached, DAX, MemoryDB aur aaj ke durability options','<b>Operations:</b> asli nodes/AZs, TLS/RBAC, limit wali failures aur poora kharcha','<b>Saboot:</b> origin ki asli calls, purani bharai ki race aur managed metadata ki limits'],
    hook:{when:'SHOPKARO · MAHASALE PREVIEW · COURSE KI KAHANI (FICTIONAL)',title:'“Ek product page ke 40 queries — DB ko cache chahiye, par stock galat nahi hona chahiye.”',text:'Catalogue page baar-baar khulta hai aur RDS ka CPU 95% tak pahunch jaata hai. Ravi read replica jodta hai; par asynchronous replica purana stock dikha sakta hai. Neha catalogue cache ko haan kehti hai, par checkout ka daam/stock asli (authoritative) DB transaction se hi pakka hoga. Pehle bekaar N+1 queries theek karo; cache kharab query aur business ki galti apne aap theek nahi karta.'},
    steps:[
      {q:'Cache asli duniya ki kaunsi problem solve karta hai?',analogy:'Dukaan counter par popular catalogue rakhti hai; har customer ke liye godown se wahi page nahi mangwaati. Counter ki copy tez hai, par stock ki bikri godown ke asli khaate mein hi likhi jaati hai.',body:'<p>Cache ek dobara kaam aane wala result caller ke paas rakhta hai. Hit = rakha hua data mil gaya; miss = origin se laao aur aksar cache mein bhar do. Origin ke kam reads se latency aur load kam ho sakta hai, par memory, network, purana data aur refill ki failures chalane ka kharcha jodte hain.</p>',points:['Course ka catalogue 60 second purana data manzoor kar sakta hai. Checkout ke stock/daam ke niyam asli transaction se chalte hain; cache ya asynchronous replica ka data stock hone ka pakka saboot nahi.','App ke andar ka cache tez hai, par har app server ka alag hota hai; deploy/scale hone par entries kho jaati hain ya duplicate hoti hain. Shared cache reuse ek jagah karta hai, par network aur sabki ek saath failure ki dependency jodta hai. EC2 ke bahar sessions load balancing mein madad karte hain, par session ka bachna/revoke/expiry phir bhi design karna padta hai.','Sirf hit ratio safalta nahi hai. 99% hit rate par galat tenant ya purana checkout daam dikhana bug hai. Zaroori load par sahi data, origin calls, tail latency, errors aur failure fallback saath mein naapo.'],asli:'Kaam: local lab host cache ke peeche asli DynamoDB reads chalati hai. Same scope ki das catalogue requests = ek origin read aur nau hits. Yeh AWS ya Valkey ki latency ka benchmark nahi.'},
      {q:'Cache key mein kya rakhein? Request ID kyun nahi?',analogy:'Shelf ka label batata hai: product, tenant (dukaan) aur edition. Har customer ki receipt number se same public catalogue ka alag shelf banaoge, toh reuse khatam. Kisi ek customer ka quotation public shelf par rakhna privacy bug hai.',body:'<p>Key mein woh har cheez daalo jisse cache wala jawaab badalta hai: product, tenant, bhasha/currency, permission ya daam ka scope, schema/version aur zaroori query options. Request/session ke timestamps tabhi bahar rakho jab unse yeh jawaab nahi badalta. Hit ratio badhane ke liye tenant/permission ka scope kabhi mat hatao.</p>',points:['Catalogue fixture ki key JSON tuple hai: [catalog-v1, tenant, product]. Pakki encoding se delimiter ki gadbad wale takraav nahi hote. Allowed tenant/scope review kiye app context se aana chahiye; cache helper users ka login nahi karta.','Same public product ke read mein sessionId/requestTime key mein ho, toh har request par nayi entry banti hai. Node bada karne se pehle sample keys, unki ginti aur hits/misses dekho. Query result ke cache ko bhi filter/sort/page/version ka saaf scope chahiye.','Soch kar serialize karo, lautaye tenant/product ko check karo aur alag copies lautao. Purane schema ke bytes, badal sakne wale references, bahut badi values aur bina limit ki keys cache ko kharab kar sakti hain ya memory khatam kar sakti hain. Cache ki error par chupchaap kisi aur user ka record kabhi mat lautao.'],code:"# Host lab reference; existing adapter fetches the exact tenant/product\ncache = CacheAside(fetch, ttl=60, max_entries=100)\ncache.get('shop', 'kurta')\ncache.invalidate('shop', 'kurta')",asli:'Kaam: triage ek public catalogue key dekhta hai jisme sessionId aur timestamp hain. Sahi key product/tenant/jawaab ke badlav ko rakhti hai aur bina matlab ki request pehchaan hata deti hai.'},
      {q:'Cache-aside, write-through aur write-behind kab use karein?',analogy:'Counter par copy nahi hai toh godown se laao: yeh cache-aside hai. Bikri ke saath khaata aur counter dono update karo: write-through. Pehle counter par vaada, khaata baad mein: write-behind; crash hua toh bina likha vaada kho sakta hai.',body:wrap('<table><tr><th>Pattern</th><th>Flow</th><th>Trade-off</th></tr><tr><td>Cache-aside</td><td>GET → miss → DB → TTL ke saath cache</td><td>Zaroorat par bharna; miss/freshness sambhalna</td></tr><tr><td>Write-through</td><td>Write ke saath hi store/cache dono update</td><td>Write mein zyada kaam; aadhi failure sambhalna</td></tr><tr><td>Write-behind</td><td>Origin mein save hone se pehle cache/queue "ho gaya" bolta hai</td><td>Pakki queue/order/retry/kho jaane ka design chahiye</td></tr></table>'),points:['Item cache ka practical write path: pehle DB write commit karo, phir matching cache item hatao (invalidate); agla read dobara bharega. DB commit aur invalidation ek distributed transaction nahi hain. Crash ya ek saath chal rahi purani refill se purana data reh sakta hai. Version fencing, change events/repair aur limit wala TTL khatra kam karte hain.','Origin par strong GetItem se cache ke hits strong nahi ho jaate. Source replica ka lag aur beech mein chal raha purana read data ki umar badha sakte hain. Query cache ko hataana ek item key se mushkil hai, kyunki badli row kai result sets mein ho sakti hai.','Write-through un keys ko bhi bhar sakta hai jo koi padhta nahi, aur bina saaf protocol ke har aadhi failure nahi hata sakta. Durable Valkey logging cache ki write ko apne contract ke andar bachata hai; yeh kisi alag RDS write ko apne aap commit nahi karta. Checkout ke niyam ke liye phir bhi asli atomic design chahiye.'],asli:'Kaam: host test pehle dikhata hai ki DB 599 hone ke baad bhi bina invalidation ke purana 499 aata hai; phir invalidate/refill ke baad sahi 599. Ek aur test dikhata hai ki update ke dauran beech wali purani bharai phenk di jaati hai; global strong consistency ka daava nahi.'},
      {q:'TTL, eviction aur stampede kaise control karoon?',analogy:'Catalogue copy ka expiry sticker batata hai ki woh kitni der taaza maani jaayegi. Shelf bhar gaya toh purani copy hat jaati hai (eviction). Sale ke time wahi copy expire ho aur 200 customers ek saath godown bhaagein, toh bheed (thundering herd) ban jaati hai.',body:'<p>TTL batata hai entry kitni der rahegi; agar origin se hi purana result aaya tha, toh TTL use sahi nahi banata. Memory ki policy ke hisaab se eviction entries ko aksar TTL se pehle hata deti hai. Negative caching (na mile item ko bhi cache karna) baar-baar ki missing-key calls kam karti hai, par naya bana item chhote TTL ya invalidation tak chhupa sakti hai.</p>',points:['Alag keys ke expire hone ka time jitter se thoda aage-peeche karo; maximum freshness ka budget saaf rakho. Ek hot key ke liye phir bhi request coalescing chahiye: ek caller refill kare, baaki thodi der ruken ya review ki hui stale-while-revalidate policy follow karein.','Process ke andar ka lock sirf usi process ko sambhalta hai. Poore fleet ke liye distributed lock leases, version fencing, deadlines aur limit wale retries review karne padte hain. Lock refill poora hone se pehle expire ho jaaye toh kai owners ho sakte hain; ek simple SETNX recipe se "poori duniya mein bilkul ek refill" ka vaada mat karo.','Cache band hai? Origin par fallback ki concurrency/rate ki limit rakho; circuit breaker, deadline aur load shedding lagao, aur thande cache wala event test karo. noeviction memory errors lautata hai, keys nahi hataata; durable mode TTL ya eviction band nahi karta.'],asli:'Kaam: lab 20 requests ko ek asli origin read mein jodti hai, entries ki ginti par LRU lagati hai, chhote negative TTL aur errors test karti hai. Planner 200 ek saath aayi thandi requests model karta hai; sirf lamba TTL chun lene se expiry ki woh bheed theek nahi hoti.'},
      {q:'Valkey, Redis OSS, Memcached aur durable primary mein kya chunoon?',analogy:'Counter ki shelf, sorted score-board aur pakka branch khaata: teeno alag zaroortein hain. Product ke naam se durability mat maano; exact deployment aur "save hua" kehne ka contract chuno.',body:wrap('<table><tr><th>Zaroorat</th><th>Kya chuno</th><th>Review</th></tr><tr><td>Aam cache; sorted sets/sessions</td><td>ElastiCache Valkey/Redis OSS</td><td>Features/client, HA, eviction aur persistence mode</td></tr><tr><td>Simple key/value cache</td><td>Memcached</td><td>Node-based sharding mein copy hui pakki state nahi</td></tr><tr><td>Pakka in-memory primary</td><td>MemoryDB ya eligible durable Valkey 9.0+ ElastiCache</td><td>Exact durability/features/Region aur kharcha</td></tr><tr><td>DynamoDB ke baar-baar eventual reads</td><td>DAX</td><td>Supported DynamoDB APIs aur purane data ki window</td></tr></table>'),points:['Traditional node-based Valkey/Redis OSS replicas asynchronous replication use karte hain; failover mein haal ki writes kho sakti hain. Zyada replicas pakki save hui writes ka saboot nahi. Node-based Memcached ek simple bata hua cache hai; aaj ke Serverless deployment ka managed Multi-AZ design alag hai.','Aaj ElastiCache Valkey 9.0+ node-based durability Multi-AZ transactional log se data bachati hai. Synchronous acknowledgement durability ka wait karta hai; async durable mode mein 10 second tak ka data kho sakta hai, aur log 10 second se zyada peeche ho jaaye toh primary thodi der naye writes reject karta hai. Yeh sirf cluster mode enabled node-based clusters par hai, Serverless par nahi; Feature/Region/node ki eligibility check karo; yeh course mission traditional 8.0 use karta hai.','MemoryDB ab bhi pakka in-memory database ka option hai. Supported commands, operations, durability/latency, scaling, eviction aur daam compare karo; "sirf MemoryDB durable hai" purani baat hai. Leaderboard ke sorted sets Valkey/Redis-compatible stores mein chal sakte hain, review kiye rebuild/durability plan ke saath.'],asli:'Faisla: dobara ban sakne wali copy → cache design; pakka primary → saaf persistence/acknowledgement contract; ranked scores → sahi sorted-set design. "Memcached hi akela multithreaded option hai" aaj ke engines ka safe comparison nahi.'},
      {q:'HA cache ka saboot flags ke alawa kya hai?',analogy:'Building ke naksha par "do exit" likhne se do chalne layak exit nahi mil jaate. Asli exits gino, alag failure zones dekho aur chalta hua raasta check karo; sirf safety sticker kaafi nahi.',body:'<p>Traditional node-based single-shard fixture mein alag AZ mein ek primary aur ek replica banao. Multi-AZ aur automatic failover on hone chahiye, aur asli members ready. Replication asynchronous hai; clients ko DNS/topology refresh, reconnect aur limit wala retry chahiye. Read replicas aur bata hua key space alag scale ke sawaalon ka jawaab hain.</p>',points:['Private subnet group, sahi VPC/SG, app ke liye scoped port 6379, TLS, at-rest encryption aur RBAC use karo. Valkey API mein at-rest ka default abhi true hai; zaroori settings saaf set karke wapas padho. TLS encryption user ki permission ya data ke sahi hone ka saboot nahi.','Cluster mode on karne se key slots shards mein bat jaate hain, aur compatible client chahiye; ek hot key phir bhi hot reh sakti hai. Yeh simulator ek shard/cluster mode off ka model hai; ready bolne se pehle maange gaye nodes asal mein bane hone chahiye. Koi nakli protocol ya failover timing simulate nahi hoti.','Aaj ka ElastiCache Serverless scaling, replicated Multi-AZ aur TLS khud sambhalta hai. VPC endpoints support hote hain; eligible Valkey 9.0+ public endpoints ko IAM authentication aur TLS 1.3 chahiye. Node-based private cluster ki zaroorat ko yeh mat bana do ki "har naya deployment sirf VPC mein".'],code:SOLUTION.join('\n'),asli:'Kaam: main terminal public ingress theek karta hai, TLS/RBAC ke saath do nodes banata hai, wait karta hai, HA on karta hai aur asli member/AZ ka metadata padhta hai. Moto 5.2.4 mein num-cache-clusters 2 dene par bhi sirf ek member dikhta hai, flags on hone ke bawajood; lab is kami ko saaf likhti hai, HA ko pakka nahi bolti.'},
      {q:'DAX, CloudFront, API cache ya app cache?',analogy:'User ke shehar mein public brochure edge par ho sakta hai; app ka har scope wala result shared shelf par. DynamoDB ke khaas wrapper (DAX) ko SQL query tez karne wala samajhna galat pata hai.',body:wrap('<table><tr><th>Layer</th><th>Kya chuno</th><th>Limit</th></tr><tr><td>Duniya bhar ke public objects/jawaab</td><td>CloudFront</td><td>Review kiya cache key/auth/freshness</td></tr><tr><td>REST API stage ka jawaab</td><td>API Gateway cache</td><td>Paid stage cache; HTTP API alag hai</td></tr><tr><td>Aam app/query/session cache</td><td>ElastiCache ya app ke andar</td><td>Scope/expiry/eviction/failure ka design</td></tr><tr><td>DynamoDB eventual reads tez karna</td><td>DAX</td><td>Strong/transactional reads seedhe DynamoDB jaate hain</td></tr></table>'),points:['DAX RDS ko tez nahi karta. Strong reads/TransactGetItems seedhe DynamoDB tak jaate hain aur cache nahi hote; cache hua eventual read bhi purana ho sakta hai. DAX ke item cache aur query cache ka invalidation/TTL alag hai; DAX ko bypass karne wali writes cache ke results ko purana chhod sakti hain.','DAX ko VPC/subnet, compatible client, service par bharosa karne wala scoped DynamoDB role aur app ki IAM permissions chahiye. TLS endpoint 9111 use karta hai; bina encryption wala 8111. Alag failure zones mein teen nodes HA ki aam shuruaat hai, zero rukawat ki guarantee nahi.','Har user ka alag jawaab cache ho sakta hai, agar sahi isolation ho; par keys badhne par public reuse aksar khatam ho jaata hai. Access/freshness/privacy dekh kar sabse paas ki kaam ki layer chuno; zyada cache layers invalidation aur debugging ki jhanjhat badhati hain.'],code:`aws dax create-cluster --cluster-name cart-accel --node-type dax.t3.small --replication-factor 3 --iam-role-arn ${ROLE} --subnet-group-name shop-dax-private --security-group-ids sg-cache --availability-zones ap-south-1a ap-south-1b ap-south-1c --sse-specification '{"Enabled":true}' --cluster-endpoint-encryption-type TLS\naws dax describe-clusters --cluster-names cart-accel`,asli:'Kaam: interview ek scoped teen-node DAX metadata fixture banata hai, sirf us cart display ke liye jahan eventual read saaf manzoor hai. Checkout asli raaste se hi chalta hai. Simulator ke do observations ready hona dikhate hain, AWS ka time ya asli TLS/auth test nahi.'},
      {q:'Size, bill aur production debugging ka faisla kaise karein?',analogy:'Shelf ke kharche ke saath stock ka size, chalta hua working set, copy karne ka kaam aur counter ki line bhi gino. Galat catalogue wali sasti shelf bachat nahi; badi shelf har request ke alag label ko theek nahi karti.',body:'<p>Lagbhag US East public daam (2026-10-26 ko check kiye): Valkey cache.t4g.small $0.0256/node-ghanta, Redis OSS $0.032; do Valkey nodes × 720 ghante ≈ $36.86/mahina kul. Valkey Serverless $0.084/GB-ghanta, 100 MB minimum ke saath, + $0.0000000023/ECPU ($0.0023/million). Baaki serverless engines ka minimum 1 GB hai; CPU/bytes wale bhaari commands zyada ECPU lete hain.</p>',points:['Serverless: 500 GET/s × 2 ECPU × 30 din ≈ $5.96 ECPU + lagbhag $6.05 minimum storage, bharai/invalidation/network/extras se pehle. Yeh sirf request ka example hisaab hai, bill ya barabar performance wale node ka compare nahi. Naye durable sync mode ka daam alag hai; traditional 8.0 ke rates/features aankh band karke mat lagao.','Galti jo sab karte hain: overhead/fragmentation/replicas bhool kar sirf data bytes se daam lagana; replica ya cache ko asli stock maanna; key se scope hata dena; TTL na rakh kar sochna ki eviction freshness de dega; maan lena ki cache band hone par DB par bina limit fallback safe hai.','Production mein aisa hota hai: keys badalti rehti hain, eviction ke toofan aate hain, badi values kaam rok deti hain, thande deploys origin par bheed bhejte hain, replicas peeche rehte hain, purani bharai invalidation se takraati hai, aur retries DB ko gira dete hain. Hits/misses, evictions, memory/CPU/network, replication lag, origin QPS, errors aur p95/p99 saath dekho.','Interview ke sawaal: jawaab ke kaun se badlav key mein jaane chahiye? DB commit safal ho aur invalidation fail ho toh? Kai servers par refill kaise sambhaloge? Saare cache nodes fail hon toh kya bachega? Freshness aur checkout ke sahi hone ka owner kaun?'],asli:'Faisla kaise karein: reuse hai? Nahi → pehle query/key theek karo. Freshness manzoor hai? Nahi → asli raasta. Public/global → edge socho. Aam app cache → zaroorat ke hisaab se Valkey/Memcached. DynamoDB ke eventual reads → DAX socho. Pakka primary → review kiya MemoryDB/eligible durable Valkey. Size naape hue working set aur failure ke load se tay karo.'}
    ],
    myth:[{myth:'“Hit ratio zyada hai, toh data apne aap sahi hai.”',sach:'Scope, source ki umar, invalidation aur checkout ke asli niyam maayne rakhte hain. 99% hits par galat tenant ya purana stock bhi bug hi hai.'},{myth:'“Multi-AZ ka flag on hai, matlab do chalne layak cross-AZ nodes hain.”',sach:'Asli members, roles, AZs aur ready hona dekho. Moto ke flag/member ka farak saaf likha hai; asli failover/TLS ka saboot nahi.'},{myth:'“TTL har expiry ki bheed theek karta hai; ek local lock poore fleet ko sambhal leta hai.”',sach:'Jitter alag keys ko aage-peeche karta hai; hot key ki coalescing ke liye review kiya scope/lease/fencing design, deadlines aur bachai hui origin capacity chahiye.'},{myth:'“Saara ElastiCache thodi der ka hai; durable mode eviction rok deta hai.”',sach:'Aaj ke eligible Valkey 9.0+ mein saaf durability options hain. TTL/eviction ki policy phir bhi lagti hai; MemoryDB bhi pakke primary ka ek option hai.'}],
    playbook:{title:'Cache kab aur kahan: pehle sahi data',use:['Baar-baar ke mehenge catalogue/query reads, jahan freshness/privacy ka scope manzoor ho','Sorted sets/session designs, soch kar rakhi expiry, rebuild aur persistence contract ke saath','Sahi DynamoDB eventual reads ke liye DAX; jawaab share ho sake toh edge/API layer'],avoid:['Checkout ka asli stock/daam purane cache ya peeche chalte replica se nikaalna','Hits badhane ke liye key ka scope hata dena; jawaab badle bina request IDs jod dena','Paise/inventory ke liye bina limit ke retries/fallback ya bina review ka write-behind'],how:['Dobara kaam aane wala jawaab, allowed scope aur freshness ka budget likho','Tareeka/layer chuno, aur invalidation/bharai fail hone ka saaf protocol','Working set/overhead, cache aur origin ka peak load naapo, phir poora kharcha','Asli members/AZs/security settings dekho; thanda cache, failure aur data races chala kar dekho'],redflags:['Har request par nayi keys; bada node hone par bhi kam reuse','HA flag on, par doosri AZ mein ready replica nahi','Origin ke strong read ko cache ka strong jawaab bolna','Maan lena ki durability TTL/eviction rokti hai ya kisi alag DB ka asar bachati hai'],rule:'Reuse/scope → freshness/niyam → tareeka/layer → limit wali refill/failure → naapa size/kharcha aur asli data ka saboot.'},
    exam:[{cue:'"repeated DB reads; general app cache"',pick:'ElastiCache candidate',why:'Data ka reuse, freshness, keys aur origin ke bachav wala fallback check karo.'},{cue:'"DynamoDB eventual reads; microsecond acceleration"',pick:'DAX',why:'Strong/transaction reads seedhe jaate hain; client/VPC/IAM aur purane data ki window maayne rakhti hai.'},{cue:'"ranking / leaderboard"',pick:'Valkey/Redis-compatible sorted set ek option',why:'Rebuild/durability aur hot key review karo; ek gameId partition + DAX har jagah ka ilaaj nahi.'},{cue:'"session outside app instance"',pick:'Review kiya shared state store',why:'ElastiCache/DynamoDB ya sahi durable option; expiry/revoke/availability phir bhi chahiye.'},{cue:'"durable in-memory primary"',pick:'MemoryDB ya eligible durable Valkey 9.0+ ElastiCache',why:'Exact persistence acknowledgement/features chuno, sirf service ke naam wala purana niyam nahi.'},{cue:'"simple node-based key/value cache"',pick:'Memcached candidate',why:'Sorted-set/replication ki khaas zaroorat nahi; serverless deployment alag hai.'},{cue:'"hot key expires; origin spikes"',pick:'Coalescing + TTL jitter aur limit wala fallback',why:'Sirf jitter ek hi key ki ek saath aayi requests ko nahi sambhal sakta.'},{cue:'"global public response / REST API stage"',pick:'CloudFront / API Gateway cache',why:'Cache key/auth/freshness review hui; HTTP API ke features alag hain.'},{cue:'"Multi-AZ cache needed"',pick:'Asli ready cross-AZ primary/replica + automatic failover',why:'Control-plane ka flag node ki jagah ya asli failover ka saboot nahi.'}],
    stages:[
      {type:'dryrun',title:'🔬 Thanda miss, daam ka update aur refill ki bheed',goal:'Har click par data ka owner aur origin calls dekho. Teen faislon mein freshness/scope/refill ka contract chuno.',nodes:[N('app',150,255,{label:'Catalogue API'}),N('cache',500,125,{label:'Scoped cache'}),N('rds',850,255,{label:'Origin DB'})],edges:[{from:'app',to:'cache'},{from:'cache',to:'rds'},{from:'app',to:'rds',dashed:true}],panels:[{id:'data',title:'Data / freshness'},{id:'load',title:'Origin / refill'}],steps:[
        {say:'Catalogue API shop/kurta maangti hai. Jawaab ke scope wali pakki key cache mein nahi hai. Ek leader origin padhta hai; cache miss aam baat hai aur uska raasta limit mein hona chahiye.',flows:[{from:'app',to:'cache',label:'GET',tone:'slow'},{from:'cache',to:'rds',label:'miss',tone:'slow'}],nodes:{cache:{tone:'idle',badge:'cold'},rds:{tone:'busy',badge:'1 actual read'}},panels:{data:['Key: catalogue schema + allowed tenant + product','Origin returns 499/version 1'],load:['Local lab: 1 thandi request → 1 DynamoDB GetItem','Course workload: har thande page par 40 SQL queries ek alag fixture hai']}},
        {say:'Cache 60 second TTL ke saath copy rakhta hai. Same scope ke baar-baar ke catalogue reads copy se milte hain. Checkout phir bhi asli daam/stock check karta hai.',flows:[{from:'app',to:'cache',label:'hit',tone:'ok'}],nodes:{cache:{tone:'ok',badge:'499/v1;TTL 60'}},panels:{load:['Local lab: 10 requests → 1 origin read + 9 hits','Cache hit aaj ka stock prove nahi karta']},ask:Q('Checkout ko daam aur bache stock ke niyam kahan laagu karne chahiye?','Asli transaction ka raasta use karo; cache wale catalogue ki purane data ki window manzoor hai',['Sirf catalogue cache use karo, kyunki zyada hit ratio har result ko strong aur taaza bana deta hai','Peeche chalta read replica akela use karo, kyunki replicas primary ki har transaction ko accept karte hain','Sabse purani in-process session copy use karo, kyunki TTL asli daam ko hamesha ke liye pakka rakhta hai'],0,'Asli transaction niyam bachata hai. Cache hits strong consistency nahi; asynchronous replicas peeche reh sakte hain; session copies/TTL stock ya na badalne wale daam laagu nahi karte.')},
        {say:'Origin 599/version 2 commit karta hai. Bina invalidation ke cache ab bhi 499 de sakta hai. Commit karo, phir item key invalidate karo; agla miss dobara bharega. Yeh do operations ek distributed transaction nahi.',nodes:{rds:{tone:'new',badge:'599/version 2'},cache:{tone:'slow',badge:'old499 until repair'}},panels:{data:['Origin ka strong read baad ke cache hits ko strong nahi banata','Source ka lag aur beech ki bharai data ki umar badha sakti hai']},ask:Q('"DB write + cache invalidate" design mein kya missing hai?', 'Aadhi failures aur beech ki purani bharai review karo; limit wali freshness/repair/versioning lagao',['Maan lo dono calls atomic hain, kyunki dono ek hi app process chalata hai','Write se pehle invalidate karo aur maan lo ki koi saath chalta reader purane bytes dobara nahi bharega','Entry ko TTL mat do, kyunki eviction purana data business ki exact deadline par hata dega'],1,'DB/cache calls atomic nahi hain. Write se pehle invalidation purani bharai se takra sakta hai; TTL/repair/version fencing ka review chahiye. Eviction memory ki policy hai, freshness ki exact deadline nahi.')},
        {say:'Ek test gate purane data ko publish hone se pehle rok deta hai. DB 699/version 3 commit karta hai aur invalidation us bharai ko bekaar mark karta hai. Reference cache purani bharai phenk kar dobara laata hai.',flows:[{from:'cache',to:'rds',label:'refetch',tone:'ok'}],nodes:{cache:{tone:'new',badge:'publish699/v3'}},panels:{data:['Host par asli race: 2 origin reads, aakhir mein 699/version 3','Sirf ek process ka taalmel; poore fleet ke lock ka daava nahi']}},
        {say:'200 requests ek saath ek thandi hot key dekhti hain. Sirf TTL poori bheed origin par bhej deta hai; coalescing se ek leader limit wale scope mein refill karta hai.',nodes:{cache:{tone:'busy',badge:'cold hot key'},rds:{tone:'slow',badge:'overload risk'}},ask:Q('Ek saath expire hone wali requests ke liye sabse achha scoped bachav?', 'Deadlines ke saath refills jodo, origin ki capacity bachao aur baaki keys ki expiry aage-peeche karo',['Sirf TTL badhao aur maan lo ki aage ke saare thande deploys ya key evictions khatam','Har key mein request ka timestamp jodo, taaki har request apna result alag cache kar sake','DB par bina limit fallback do, taaki cache failure par retry ya load-shedding ki limit na chahiye'],2,'Coalescing/deadlines aur limit wala fallback origin ko bachate hain; jitter alag keys ko phailaata hai. Lamba TTL saare thande events nahi hataata; timestamps reuse khatam karte hain; bina limit fallback DB gira sakta hai.')},
        {say:'Host lab mein 20 ek saath requests ek asli origin read use karti hain, 19 jud kar intezaar karti hain. Managed cache ka HA/TLS metadata ek alag manzoori ka check hai; host refill ya AWS performance ka saboot nahi.',nodes:{cache:{tone:'ok',badge:'1 leader+19 waiters'},rds:{tone:'ok',badge:'1 origin read'}},panels:{load:['Ginti control ki gayi concurrency se, RPS/p99 benchmark nahi','Local cache Valkey/DAX server nahi hai'],data:['Source ka tenant/product/version check hua','Galat tenant ya purani bharai ka publish manzoor nahi']}}
      ],lesson:'Sirf dobara kaam aane wale scoped jawaab cache karo. Asli niyam, invalidation ki race aur limit wala thanda/failure load saaf rakho.'},
      {type:'flowlab',title:'🎛️ Hit ratio, DB load aur cache ki freshness',goal:'Kam se kam 1000 catalogue reads/s aur 3 writes/s rakho. Pakki scoped key, kaafi cache budget, TTL ≤60 s aur coalesced refill chuno. Try karo: TTL 60, 4 MiB, pakki key, coalesced refill.',scenario:'Bataya model: 1000 barabar products, har value 2 KiB × 1.5 memory overhead; har miss par origin ki 40 SQL queries. Reads/writes barabar Poisson aur origin turant taaza maana gaya. Writes matching items ko invalidate karti hain. Source ka lag/races/failure ki umar bahar hai; yahan TTL model mein cache ka rehna hai, production mein end-to-end freshness ki guarantee nahi.',knobs:[
        {id:'reads',label:'Catalogue reads',min:500,max:1500,step:500,value:1000,fmt:n=>n+' /s'},
        {id:'writes',label:'Catalogue updates',min:1,max:5,step:2,value:3,fmt:n=>n+' /s'},
        {id:'ttl',label:'TTL maximum',min:10,max:90,step:10,value:10,unit:' s'},
        {id:'memory',label:'Usable fixture budget',min:1,max:4,step:1,value:1,unit:' MiB'},
        {id:'key',label:'Key design',min:0,max:1,step:1,value:0,labels:{0:'Per-request',1:'Stable scope'}},
        {id:'refill',label:'Cold hot-key refill',min:0,max:1,step:1,value:0,labels:{0:'200 leaders',1:'Coalesced'}}
      ],model:k=>{const p=plan(k);return {readouts:[{label:'Modeled hit ratio',value:(p.hit*100).toFixed(1)+'%',tone:p.hit>=.95?'ok':'bad'},{label:'Origin read queries',value:Math.round(p.db)+' queries/s',tone:p.db<=1000?'ok':'bad'},{label:'TTL residency window',value:k.ttl+' s · fresh-origin model',tone:k.ttl<=60?'ok':'bad'},{label:'Thandi bheed mein origin calls',value:p.burst+' for 200 requests',tone:p.burst===1?'ok':'bad'},{label:'Serverless gross/month',value:'approx $'+p.serverless.toFixed(2),tone:'acc'},{label:'Do chhote nodes, kul/mahina',value:'approx $'+p.nodes.toFixed(2),tone:'acc'}],verdict:{ok:p.ok,text:p.ok?'Zaroori load bacha; model mein hits ≥95%, origin queries ≤1000/s, TTL ≤60 s aur coalesced refill. Production se pehle source ki umar, distributed taalmel aur asli memory/latency check karo.':k.reads<1000||k.writes<3?'Zaroori read/write traffic kam karke jeet nahi milegi.':!k.key?'Har request ki key reuse khatam karti hai. Jawaab ka scope rakho; bina matlab ki request pehchaan hatao.':k.ttl>60?'Lamba TTL bataye display freshness budget ko todta hai.':p.capacity<1?'Working set bataye memory budget mein fit nahi hota; asli size ke liye naapa hua overhead bhi chahiye.':!k.refill?'Ek thandi hot key ab bhi 200 origin requests bhejti hai. Lamba TTL bheed theek nahi karta.':'Hit ratio/origin load ko 60 second ke budget se compare karo. Capacity, expiry aur writes, teeno reuse par asar daalte hain.'}};},check:k=>plan(k).ok,lesson:'Course ka model: item ki umar = min(TTL, agli write), barabar reads aur entry budget ka hissa. Serverless andaaze mein har 2 KiB GET/bharai par 2 ECPU + har invalidation par 1, aur 100 MB minimum storage; 2026-10-14 ke catalog ke lagbhag US East rates. Do nodes ka $36.86 sirf compute hai. Source DB, asli CPU weights, network, backup, credits aur tax bahar; 1..4 MiB ka virtual budget koi khareedne wala node size nahi.'},
      {type:'bins',title:'🗂️ Key ka scope: public catalogue ka contract',instructions:'Cache key mein sirf woh cheezein daalo jinse page badalta hai: kaun si dukaan (tenant), kaun sa product, kaun si bhasha aur currency, aur data ka version. Public page sab users ke liye same hai. Isliye session ID ya request ka time key mein mat daalo. Discount wale private page ka cache alag rakho.',bins:[{id:'include',label:'Is key mein daalo'},{id:'exclude',label:'Is public jawaab ke liye bahar rakho'}],items:[{text:'Authorized tenant',bin:'include',explain:'Tenant jawaab aur isolation ki boundary hai; allowed scope alag se nikaalo.'},{text:'Product ID',bin:'include',explain:'Alag products ka data alag hai.'},{text:'Bhasha/currency, jab jawaab badalta hai',bin:'include',explain:'Jo cheezein dikhne wali values badalti hain, unhe daalo.'},{text:'Pakka schema/deployment version',bin:'include',explain:'Purane, na milne wale format ka data padhne se bachao.'},{text:'Unrelated per-request timestamp',bin:'exclude',explain:'Har request par naya timestamp is public jawaab ko badle bina reuse khatam kar deta hai.'},{text:'Same public catalogue ke liye session ID',bin:'exclude',explain:'Is fixture mein session se kuch nahi badalta; har user ke alag jawaab ko sahi permission scope chahiye.'}]},
      {type:'match',title:'🔗 Control ka purpose',instructions:'Har mechanism ko uske sahi contract se jodo.',pairs:[{left:'TTL',right:'Entry kitni der rahegi, uski limit; source ki freshness phir bhi maayne rakhti hai',explain:'Expiry transaction nahi, na guarantee ki source data naya tha.'},{left:'Request coalescing',right:'Taalmel ke scope ke andar ek refill leader',explain:'Process ke andar ki coalescing poore fleet ko nahi sambhalti.'},{left:'DB commit ke baad invalidate',right:'Matching copy hatao; beech ka gap (atomic nahi) sambhalo',explain:'Write ki failure aur beech ki purani bharai ka review phir bhi chahiye.'},{left:'Eviction policy',right:'Memory bharne par behaviour, freshness ki zaroorat se alag',explain:'Durability apne aap eviction/TTL band nahi karti.'},{left:'DAX strong read',right:'Seedha DynamoDB tak jaata hai; cache item se nahi milta',explain:'DAX ki tezi eligible eventual reads ke liye hai.'},{left:'Multi-AZ flag',right:'Config jise asli ready nodes/AZs se check karna hai',explain:'Sirf flags asli HA/failover ya TLS/network ka behaviour prove nahi kar sakte.'}]},
      {type:'triage',title:'🩺 Hit ratio 20%: node chhota hai ya key galat?',symptom:'Course ke data mein 1000 public catalogue requests par 200 hits aur 800 misses hain. Same tenant/product/currency dobara aate hain, phir bhi har request par keys badh rahi hain. AWS/Moto ka asli metric pakadne ka daava nahi.',goal:'Sample keys aur workload ka saboot dekho, phir asli wajah aur safe repair chuno.',commands:[
        {cmd:'aws logs tail /shopkaro/catalog-key-samples',out:'tenant=shop product=kurta currency=INR key=catalog:shop:kurta:INR:session-18:ts-101\ntenant=shop product=kurta currency=INR key=catalog:shop:kurta:INR:session-21:ts-102\nresponseScope=public; responseBytesIdentical=true',clue:true,note:'Bina matlab ke session/timestamp same public jawaab ki keys badal dete hain.'},
        {cmd:'aws logs tail /shopkaro/catalog-cache-summary',out:'requests=1000 CacheHits=200 CacheMisses=800 OriginReads=800\nuniqueResponseScopes=20 uniqueCacheKeys=820',clue:true,note:'Memory khareedne se pehle jawaab kitne alag hain aur keys kitni alag hain, compare karo.'},
        {cmd:'aws elasticache describe-cache-clusters --cache-cluster-id catalog-cache-001 --show-cache-node-info',out:'{"CacheClusters":[{"Engine":"valkey","CacheClusterStatus":"available","CacheNodeType":"cache.t4g.small"}]}',clue:false,note:'Ready node/type se sahi keys, memory ki jagah ya data ki freshness prove nahi hoti.'}
      ],questions:[
        Q('Sample mein kam reuse ki sabse seedhi wajah kya hai?', 'Session/timestamp same public jawaabon ko har request ki alag cache entries mein tod dete hain',['TLS encryption har catalogue value ko apne aap ek alag product ka jawaab bana deta hai','Multi-AZ promotion ke liye har request ko nayi random cache key chahiye, sahi hone ke liye','Doosra replica app ke key design ka hit ratio par saara asar hata deta hai'],0,'Sample ki keys jawaab ke scope se zyada badalti hain. TLS logical jawaab nahi badalta; HA ko random keys nahi chahiye; replicas har request ki key theek nahi kar sakte.'),
        Q('Kaunsa repair jawaab ka isolation rakhte hue reuse badhata hai?', 'Tenant/product/currency/schema ka scope rakho; bina matlab ke session/timestamp hatao',['Har key se tenant aur currency hata do, kyunki shared product ID hamesha kaafi hai','Request ka timestamp rakho aur node bada karte raho jab tak har request repeat hit na ban jaaye','Sirf zyada hit ratio par bharosa karo aur badlav ke baad cache ka daam ya permission check mat karo'],1,'Jawaab/permission ka asli badlav key mein rakho. Tenant/currency hataane se galat data leak ho sakta hai; badi memory kabhi na dohraayi keys ko reuse nahi kar sakti; key badalne ke baad data/freshness check karo.')
      ]},
      {type:'terminal',title:'🖥️ Private catalogue cache: asli readiness',instructions:'Network/subnet/RBAC fixtures pehle se hain. Do chhote nodes lagbhag $36.86/mahina ke kul compute mein fit hain; budget extra ya bade nodes allow nahi karta. Scope sirf control-plane ka ready hona hai, GET/SET ya naapa failover nahi.',goal:'<p><b>1 — Network:</b> sg-cache se 0.0.0.0/0 wala TCP 6379 hatao, phir TCP 6379 sirf sg-app se allow karo. App SG aur saara DB/cart data bachao.</p><p><b>2 — Banao:</b> catalog-cache, Valkey 8.0, cache.t4g.small, num-cache-clusters 2, AZ-a/b; shop-cache-private subnet group, sg-cache, TLS/at-rest encryption aur catalog-app RBAC group. replication-group-available ka wait karo.</p><p><b>3 — HA on:</b> modify-replication-group se automatic failover + Multi-AZ aur apply-immediately; phir ready hone ka wait. Shuru se sahi HA flags bhi asli sahi config hai.</p><p><b>4 — Dekho:</b> describe-replication-groups mein aaj ka available group, AZ-a/b mein asli primary + replica, sahi permissions/encryption aane chahiye. Khaali waiter output ya sirf on flags kaafi nahi.</p>',account:seed(),tasks:TASKS,solution:SOLUTION,hints:['Pehle se bana subnet/SG/RBAC fixture dekho; TLS permission nahi hai, aur HA ko asli cross-AZ replica chahiye.',SOLUTION.slice(0,2).join(' phir '),SOLUTION.slice(2,4).join(' phir '),SOLUTION.slice(4).join(' phir ')],success:AG.allOf(TASKS),successText:'Private port sirf app SG tak; asli data bacha; do-node Valkey fixture do AZ mein encryption/RBAC aur HA ke saath ready hai. Aaj ka asli member readback match karta hai. Cache hit, packet, IAM/TLS runtime ya failover ke time ka daava nahi.'},
      {type:'docker',title:'🐳 Lab16: origin calls ki asli ginti aur data races',project:'16-cache-aside',goal:'Host par cache-aside ke data/ginti tests chalao, phir apne thodi der ke Moto servers par managed cache API ki asli kamiyan dekho.',why:'Host ka data/race ka saboot aur managed service ka metadata alag sawaalon ke jawaab hain. Docker Valkey wala hissa install hone tak baaki hai; use poora hua runtime nahi dikhaya gaya.',steps:[{text:'cache.py/test_cache.py padho; asli origin read, invalidation aur concurrency tests chalao.',cmd:'source ../env.sh && ../.venv/bin/python -I test_cache.py',expect:'34 behaviour checks; 10 reads → 1 origin + 9 hits; 20 ek saath → 1 origin + 19 jude hue; beech ki race 699/version 3 lautati hai. Apni tables [] aur server band.'},{text:'Ek aur apne thodi der ke server par metadata probe chalao; flags dekh kar HA bolne ki jagah limits dekho.',cmd:'../.venv/bin/python -I metadata.py',expect:'num-cache-clusters 2 dene par Moto sirf ek member banata hai; support na hone wali APIs likhi hain. Apna listener band, koi shared reset nahi.'},{text:'Docker aane ke baad README ka Docker wala hissa padho; yahan woh check nahi hua.',expect:'Host cache ya metadata se Valkey/DAX runtime, asli TLS/HA ya AWS performance ka andaaza mat lagao.'}],observe:Q('Lab16 ne asal mein kya check kiya?', 'Host cache ka data/ginti/race behaviour; managed cache metadata ki kamiyan saaf likhi',['Asli Valkey container chala aur managed TLS failover naape gaye SLA ke andar poora hua','Har Multi-AZ on flag ke peeche alag AZ mein do chalte cache members the','Origin ke strong reads ne baad ke saare cache results globally strong bana diye'],2,'Host ke reads aur control ki gayi races asli saboot hain. Docker/managed TLS/failover nahi chale; flags ke bawajood Moto ne ek member lautaya; strong source reads ke baad bhi cache ki apni purani window rehti hai.')},
      {type:'quiz',title:'🎓 Cache ke trade-offs aur failure ke contracts',questions:[
        Q('Public product ka jawaab har session mein same hai, par tenant/currency alag hain. Key ka tareeka?', 'Tenant/product/currency/schema ka scope rakho; har request ka bina matlab session/timestamp hatao',['Sirf product rakho aur maan lo ki tenant ya currency cache isolation par kabhi asar nahi daalte','Random request ID jodo, taaki har request safe tarike se same rakha public jawaab reuse kare','Ek hi constant key use karo, kyunki same route path ka matlab same allowed payload hai'],0,'Key asli jawaab ke scope se match honi chahiye. Sirf product tenant/currency chhod deta hai; random request ID reuse khatam karta hai; ek constant key permission aur jawaab ke badlav ko bhool jaati hai.'),
        Q('DB write safal hui, phir cache invalidation fail ho gaya. Kaunsi baat sahi hai?', 'Cache purana reh sakta hai; limit wali freshness, repair/change events aur race ko samajhne wala design lagao',['DB write apne aap rollback ho jaati hai, kyunki cache aur database ek transaction boundary share karte hain','Lamba cache TTL har purani entry ko turant safal DB update dikhane par majboor karta hai','Read replicas purani cache entry ko aaj ka bana dete hain, chahe cache ko koi update na mile'],1,'DB/cache updates atomic nahi hain. TTL/repair/change processing aur beech ki bharai maayne rakhte hain; lamba TTL purane data ko aur lamba kar sakta hai; replicas alag cache ko apne aap update nahi karte.'),
        Q('Badi bheed ke dauran ek hot key expire ho jaati hai. Sahi bachav kya hai?', 'Deadlines/fencing scope ke saath refill jodo; jitter aur limit wala origin fallback lagao',['Sirf memory badhao, kyunki node ka physical size har key ke liye ek refill pakka karta hai','Sirf TTL badhao, kyunki uske baad expiry, eviction aur thanda deploy ho hi nahi sakte','Har caller ko DB par bina limit retry karne do, taaki har miss ko taaza copy mile'],2,'Coalescing + bachaya origin + jitter failure ke load ko sambhalte hain. Sirf memory/TTL saare thande events nahi rokte; bina limit retries bheed badhate hain. Fleet ke taalmel ke liye saaf scope/leases/fencing chahiye.'),
        Q('DynamoDB wale view ko strong ya transactional reads chahiye. DAX par iska kya asar?', 'Woh reads seedhe DynamoDB tak jaate hain aur cache item se tez nahi hote',['Cluster par Multi-AZ on karne ke baad strong reads DAX ke item cache se milte hain','DAX apne role se RDS SQL transactions ko apne aap DynamoDB transactions mein badal deta hai','DAX ko kabhi compatible client ya VPC raasta nahi chahiye, kyunki har endpoint public HTTP API hai'],3,'DAX eligible eventual reads cache karta hai; strong/transaction reads seedhe jaate hain. Multi-AZ cache ko strong nahi banata; DAX RDS ka translator nahi; DAX ko compatible client aur VPC/IAM connection chahiye.'),
        Q('Pakka in-memory primary storage chahiye. Aaj ki salah kya hai?', 'MemoryDB ko eligible durable Valkey 9.0+ options aur exact write/eviction contracts se compare karo',['Maan lo har ElastiCache node thodi der ka hai, kyunki managed caches kabhi writes save nahi kar sakte','Kisi bhi replica ko pakka acknowledgement maano, kyunki asynchronous replication data nahi khoti','TTL mat rakho aur maan lo ki memory bharne wali eviction ab app ki keys nahi hata sakti'],0,'Aaj ka Valkey 9.0+ set ki hui Multi-AZ log durability support karta hai; MemoryDB bhi ek option hai. Async replicas haal ki writes kho sakte hain; sirf TTL na rakhne se memory policy wali eviction nahi rukti.'),
        Q('Managed cache ke HA flags on karne ke baad members/AZs kyun dekhein?', 'Asli ready primary/replica alag AZ mein hone chahiye; sirf on flags se yeh pakka nahi hota',['Member ki ginti se farak nahi padta, kyunki ek node apne aap alag standby AZ de deta hai','Safal describe se prove hota hai ki saare TLS, IAM aur network requests chal gaye','Simulator ka har waiter production ke liye AWS failover ka exact time naapta hai'],1,'Asli ready cross-AZ members maayne rakhte hain. Ek node replica nahi hota; metadata TLS/IAM/packets nahi chalata; simulator ke waiters state dikhate hain, time ya production failure drill nahi.'),
        Q('Cache ka hit ratio zyada hai, par source replica ke lag ki wajah se purana catalogue lautata hai. Matlab?', 'Hits reuse naapte hain; source ki umar + TTL/bharai ka behaviour freshness tay karta hai',['Zyada hit ratio prove karta hai ki source replica ka lag copy hui catalogue value par asar nahi daal sakta','Kisi aur alag table par strong reads har purani cache entry ko turant refresh karwa dete hain','Eviction policy business ke timestamps se entries ko exact expiry par gayab karti hai'],2,'Reuse freshness nahi hai. Peeche chalta source purana data bhar sakta hai; alag strong reads cache ko invalidate nahi karte; eviction memory ka kaam hai, business ke time ka niyam nahi.'),
        Q('ElastiCache node vs serverless ka kharcha compare karne ke liye kya chahiye?', 'Naapi gayi storage/CPU ya ECPU activity, replicas, minimums aur barabar zarooraton ka poora kharcha',['Sirf kachche object bytes, kyunki fragmentation, commands aur replicas memory/kharche par asar nahi daalte','Sirf node ka ghante ka rate, kyunki serverless mein na minimum storage hai na request processing charge','Sirf sahi engine ka naam, kyunki har Region aur durability mode ka daam ek jaisa hai'],3,'Barabar zarooraton par asli memory/command/load/kharche ke meters se compare karo. Kachche bytes overhead/replicas bhool jaate hain; serverless ke minimums/ECPUs hain; Region/engine/durability ke chunav daam badal sakte hain.')
      ]}
    ],
    interview:{title:'Interview: freshness, failure aur cache ka chunav',instructions:'Chaar faislon ke baad eventual cart-display wale DAX fixture ko asli ready metadata tak banao aur dekho.',questions:[
      Q('Interviewer: “Origin ka GetItem strong hai, isliye cache ke hits bhi strong hain?”', 'Nahi; strong source read ke bawajood cache copies ki apni umar aur invalidation ka contract hai',['Haan; pehla strong read aage ki har cache copy ko hamesha ke liye strong bana deta hai','Haan; TTL sirf memory ke use par asar daalta hai aur cache ke jawaab ke sahi hone ko nahi badal sakta','Nahi; ek hi ilaaj hai tenant scope hatana, taaki saare callers bilkul same cache bytes padhein'],3,'Origin ka strong read sirf us read ke time par laagu hota hai. Baad ke cache hits purane ho sakte hain; TTL purani window par asar daalta hai; tenant scope hataana consistency nahi, privacy/data ka bug banata hai.'),
      Q('Peak ke time catalogue cache band hai. Fallback ko kya bachana chahiye?', 'Origin ki capacity: limit wali concurrency, deadlines/backoff aur soch kar load shedding',['Sirf hit ratio, kyunki cache band hone se origin ki requests ya queue nahi badalti','Saari requests bina limit retries ke saath, kyunki retry karne se aage ka load hamesha kam hota hai','Sirf cache process ka uptime, kyunki cache theek hone tak purana checkout stock safe hai'],0,'Fallback bheed ko DB par bhej sakta hai. Kaam aur deadlines ki limit rakho; sirf hit ratio/uptime origin ka overload aur data ka sahi hona bhool jaate hain; bina limit retries failure badhate hain; stock ko phir bhi asli check chahiye.'),
      Q('Kya process ka lock kai servers wale fleet mein ek hi refill pakka karta hai?', 'Nahi; taalmel ka scope, lease expiry, version fencing aur retry deadlines design karni padti hain',['Haan; ek database se judne bhar se har app server wahi Python lock share karta hai','Haan; lamba TTL saare deploy, eviction aur outage wale thande misses rok deta hai','Nahi; har caller ko unique key chahiye, kyunki distributed caches results share nahi kar sakte'],1,'Local lock ka scope ek process hai. Shared origin lock share nahi karta; TTL saare thande events nahi hataata; unique keys reuse khatam karti hain. Distributed taalmel ko expiry aur purane owners sambhalne padte hain.'),
      Q('Catalogue RDS par hai; baar-baar ke eventual cart views DynamoDB par. Cache ke options?', 'RDS ke aage aam scoped cache lagao; eligible eventual DynamoDB views ke liye DAX socho',['DAX RDS ki SQL aur transaction history ko apne aap cache items mein badal deta hai','Ek public constant CloudFront key saare customers ke private carts safe share karti hai','Koi bhi read replica checkout stock aur har cache daam ko turant asli bana deta hai'],2,'Aam cache RDS ke aage lag sakta hai; DAX sirf DynamoDB ke eligible eventual reads ke liye hai. DAX SQL translate nahi karta; private cart ki keys/auth public constant nahi ho sakti; replicas/cache checkout ki asli global state nahi.'),
      {terminal:(()=>{const a=seed();a.securityGroups[1].ingress=[{protocol:'tcp',fromPort:9111,toPort:9111,sourceGroup:'sg-app'}];const create=`aws dax create-cluster --cluster-name cart-accel --node-type dax.t3.small --replication-factor 3 --iam-role-arn ${ROLE} --subnet-group-name shop-dax-private --security-group-ids sg-cache --availability-zones ap-south-1a ap-south-1b ap-south-1c --sse-specification '{"Enabled":true}' --cluster-endpoint-encryption-type TLS`,describe='aws dax describe-clusters --cluster-names cart-accel';
        const find=s=>(s.account.daxClusters||[]).find(g=>g.id==='cart-accel');const tasks=[{text:'Asli data/network/role bacha; port 9111 sirf app SG tak',check:s=>preserve(s)&&privateRule(s,9111)&&(s.account.cacheGroups||[]).length===0},{text:'Asli DAX fixture mein 3 AZ mein 3 available nodes, scoped DynamoDB role, TLS/SSE',check:s=>{const g=find(s);return !!g&&s.account.daxClusters.length===1&&g.status==='available'&&g.nodeType==='dax.t3.small'&&g.roleArn===ROLE&&g.subnetGroup==='shop-dax-private'&&g.vpcId==='vpc-shop'&&g.securityGroupIds.length===1&&g.securityGroupIds[0]==='sg-cache'&&g.tls&&g.sse&&g.nodes.length===3&&g.nodes.every(n=>n.status==='available')&&new Set(g.nodes.map(n=>n.az)).size===3;}},{text:'Aakhri result 3 available nodes aur encrypted endpoint 9111 dikhata hai',check:s=>{const g=find(s),r=s.cacheRead?.service==='dax'&&s.cacheRead.groups.find(r=>r.id==='cart-accel');return !!g&&!!r&&r.revision===g.revision&&r.record.Status==='available'&&r.record.ActiveNodes===3&&r.record.ClusterDiscoveryEndpoint.Port===9111;}}];
        return {title:'🖥️ Eventual cart display ke liye DAX',goal:'<p>VPC/subnet/SG aur DAX par bharosa karne wala scoped read role pehle se hain. Checkout asli raaste se hi chalta hai; sirf yeh kam zaroori display eventual cache reads manzoor karta hai. cart-accel banao: dax.t3.small, replication-factor 3, shop-dax-private, sg-cache, AZ-a/b/c, TLS endpoint aur SSE ke saath.</p><p>Banane ke baad describe-clusters chalao; fixture ka pehla jawaab creating hi rehta hai. Asli teen nodes available hone tak dobara poll karo. Do tay observations course ka step hain, AWS ki der ki guarantee nahi. Galat role, bina encryption endpoint, ek node wala cluster ya delete hua source nahi chalega.</p>',account:a,tasks,solution:[create,describe,describe],hints:['DAX eligible eventual DynamoDB reads ke liye hai; read role, private raasta aur encrypted endpoint alag controls hain.',create,describe+' phir '+describe],success:AG.allOf(tasks),successText:'Teen-node DAX metadata fixture 3 AZ mein ready hai, scoped role aur TLS/SSE endpoint metadata ke saath. Asli DAX protocol, IAM/TLS runtime, cache hit, strong read ki tezi ya failover test ka daava nahi.'};})()}
    ]},
    success:['Jawaab ka scope aur manzoor purane data ki window tay kar sakta hoon','Cache-aside/invalidation ki race, expiry ki bheed aur bachaya hua fallback samjha sakta hoon','Valkey/Memcached/DAX/edge/durable-primary options compare kar sakta hoon','Asli cache members/AZs/security metadata aur host data ke saboot ka farak bata sakta hoon'],
    homework:'<p><b>Optional, sirf approved AWS sandbox mein (paisa lagega).</b> Aaj ke Region/features/daam, budget aur sabse kam zaroori access check karo. Apne private cache/subnet/security/user groups use karo aur TLS ke saath allowed/denied client commands asal mein test karo. Fixed workload par sahi scoped payload, source/cache ki umar, hit/miss/origin ki ginti aur p95/p99 likho. Thanda start, invalidation failure, ek saath purani bharai, cache outage aur control kiya HA failover test karo, DB fallback ki limit ke saath. Checkout asli raaste par hi rakho. Durable-primary mode ho toh acknowledgement, eviction policy aur recovery alag test karo. Cleanup: sirf apne node groups/DAX/serverless caches, snapshots, user/parameter/subnet groups, test tables, roles/logs aur VPC fixtures hatao. Local Docker wala hissa user ke runtime install karne tak unverified hai; free tier ka koi vaada nahi.</p>',
    cards:[{front:'Cache hit aaj ka data prove karta hai?',back:'Nahi. Hit sirf reuse prove karta hai; scope, source ki umar, invalidation aur manzoor purani window sahi hona tay karte hain. Checkout ke niyam asli raaste par rehte hain.'},{front:'Good cache key?',back:'Jawaab/permission ke har badlav ki pakki encoding. Public catalogue bina matlab ke session/time chhod sakta hai; tenant/product/currency/schema ka scope rehta hai.'},{front:'DB commit phir invalidate: kya atomic hai?',back:'Distributed atomicity nahi. Crash/failure ka gap aur beech ki purani bharai ko review kiye version/change/repair protocol aur limit wale TTL se sambhalo.'},{front:'TTL versus eviction?',back:'TTL entry ke rehne ki limit hai; eviction memory sambhalta hai. Source ki umar TTL ke andaaze se zyada ho sakti hai; durability dono policies band nahi karti.'},{front:'Hot-key expiry?',back:'Tay kiye taalmel scope ke andar coalesce karo, baaki keys ke liye jitter, deadlines/fencing aur limit wala origin fallback. Local lock poore fleet ka nahi.'},{front:'DAX strong read?',back:'Seedha DynamoDB tak jaata hai aur cache item se nahi milta. DAX RDS cache nahi, na apne aap strong/freshness badhata hai.'},{front:'HA flag enough?',back:'Asli ready primary/replica, cross-AZ jagah aur aaj ka security metadata dekho. Asli client/failover tests alag saboot hain.'},{front:'Durable in-memory choice?',back:'MemoryDB ya eligible, set kiya durable Valkey 9.0+ ElastiCache. Acknowledgement/features/daam aur eviction compare karo. Traditional 8.0 ke replicas async hain.'}]
  }]);
})();
